        StaticItem("The Crown of the High King", "The large diamons sparkle, set into the crown on the\nfour sides. The crown represents the pinnable of\npower in Alras, having rested upon the brow of Syrio\nfor ages. Just holding the ring of ornate gold seems\nto give you a strange feeling of being lucky, making\nyou feel almost drunk. The crown is engraved: \"Syrio\nForel I, High King of Alras\".", "minecraft:golden_helmet", ""),
