        StaticItem("The brightest day", "", "minecraft:written_book", ""),
        StaticItem("Breeze of the Seven Hearts", "Built for the superiority of the thrust, this peculiar weapon is\none of lightness and mobility. Swift and passing, it slips through\nlike a breeze, striking at the moment most opportune.\nThe blade is long and slender, boasting of two cutting edges\nand a sharpened tip like no other. The guard is of swept gold,\nadorned with bronze leaves and silver feathers.\nThe figurehead of a mythical bird serves as its pommel.", "minecraft:iron_sword", ""),
        StaticItem("Budding Flower", "A small jewel of marvelous, soft pink set on a thin band of shining silver.\nThe jewel is placed right in the center of tiny, detailed petals.\nTruly made to be graced by the hands of a budding young woman.", "minecraft:diamond", ""),
        StaticItem("The Edge", "A ring of dark, blackened metal, forged in some unknown fashion.\nTo stare into the metal is to gaze into the abyss itself.\nOn the center lies the small figurehead of a bat\nwith deep crimson rubies set for eyes.\nHow utterly brooding.", "minecraft:diamond", ""),
        StaticItem("Ring of Promise", "The clear gem of glistening green\nsymbolizes a promise made between two.\nIt yearns for its twin.", "minecraft:emerald", ""),
        StaticItem("Friend of the Monarch", "It has survived a blood-stained past - a past of the sword's own doing.\nA favorite of the rulers of ages past and lands far away,\nthis sword boasts a long, slightly curved blade.\nIts single-edged sharpness has been the undoing of many a king and commoner alike.\nA solemn swan serves as the large, curved pommel of this ornate sword.\nThis blade of rulers past forgoes the use of a guard.\nAfter all, the best enemy is a dead enemy.", "minecraft:iron_sword", ""),
        StaticItem("Five Fallen by the Great Ox", "In a time long ago, this greatsword belonged to even greater hands.\nIn the hands of this great brute of a man, towering in stature, tides did turn.\nHeavy and long, the blade relished the splendor of battle.\nWith one stroke, five were slain. Soon, hundreds followed.\nIn lesser hands, the sword would never again bask in such glory.\nGreat strain would befall those unworthy of following in the giant’s footsteps.", "minecraft:iron_sword", ""),
